class ActiveQueue:
    def __init__(self):
        self._pool = ThreadPoolExecutor(max_workers=1)   # scheduler + queue
        self._servant = MQServant()

    def put(self, msg):
        return self._pool.submit(self._servant.put_i, msg)   # Future

    def get(self):
        return self._pool.submit(self._servant.get_i)

# caller: fut = q.get(); msg = fut.result(timeout=5)      # rendezvous

